@click.command("routes", short_help="Show the routes for the app.")
@click.option(
    "--sort",
    "-s",
    type=click.Choice(("endpoint", "methods", "rule", "match")),
    default="endpoint",
    help=(
        'Method to sort routes by. "match" is the order that Flask will match '
        "routes when dispatching a request."
    ),
)
@click.option("--all-methods", is_flag=True, help="Show HEAD and OPTIONS methods.")
@click.option(
    "--all-domains",
    is_flag=True,
    help="Show all domains. Defaults to using only routes on the request domain.",
)
@click.option(
    "--domain",
    "-d",
    default=None,
    help="Show only routes for the given domain.",
)
@with_appcontext
def routes_command(
    sort: str, all_methods: bool, all_domains: bool, domain: t.Optional[str]
) -> None:
    """Show all registered routes with endpoints and methods."""
    rules = list(current_app.url_map.iter_rules())

    if not rules:
        click.echo("No routes were registered.")
        return

    # Determine whether any rule targets a subdomain. If all rules use the
    # empty subdomain, there is no need for a Domain column.
    domain_supported = any(bool(rule.subdomain) for rule in rules)

    if domain is not None and not domain_supported:
        click.echo(f"No routes for domain {domain!r} were registered.")
        return

    ignored_methods = set(() if all_methods else ("HEAD", "OPTIONS"))

    if sort in ("endpoint", "rule"):
        rules = sorted(rules, key=attrgetter(sort))
    elif sort == "methods":
        rules = sorted(rules, key=lambda rule: sorted(rule.methods))  # type: ignore

    shown = rules
    if domain is not None:
        shown = [rule for rule in rules if rule.subdomain == domain]

    rule_methods = [
        ", ".join(sorted(rule.methods - ignored_methods))  # type: ignore
        for rule in shown
    ]

    if domain_supported:
        max_domain = max(len(rule.subdomain) for rule in shown, default=0)
    else:
        max_domain = 0

    headers = ("Endpoint", "Methods", "Rule")
    widths = (
        max(len(rule.endpoint) for rule in shown),
        max(len(methods) for methods in rule_methods),
        max(len(rule.rule) for rule in shown),
        )
    widths = [max(len(h), w) for h, w in zip(headers, widths)]
    row = "{{0:<{0}}}  {{1:<{1}}}  {{2:<{2}}}".format(*widths)

    if domain_supported:
        domain_header = max(len("Domain"), max_domain)
        domain_sep = "-" * domain_header
        click.echo(domain_sep + "  " + row.format(*headers).strip())

    click.echo(row.format(*("-" * width for width in widths)))

    for rule, methods in zip(shown, rule_methods):
        click.echo(row.format(rule.endpoint, methods, rule.rule).rstrip())


